package edu.campus.iitsm.shared.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * Pure domain outbound port for SLA business-hours elapsed time calculation.
 * Implemented by BusinessCalendar in the catalog domain without framework leaks.
 */
public interface WorkingTimeCalculator {

  /**
   * Computes active SLA working milliseconds between [start, end).
   * If is24x7 is true (P1/T0), returns continuous wall-clock elapsed millis.
   * Otherwise subtracts nights, weekends, and campus academic holidays.
   */
  long workingMillisBetween(Instant start, Instant end, boolean is24x7);

  default boolean isWorkingDay(LocalDate date) {
    return true;
  }
}
